with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('øve sig', 'phrase', '56823878-836c-5eb9-a444-4c4f4b1083f5', 1, 'verb', null, 'тренуватися, вправлятися', 'Hun øver sig på klaver hver dag.', 'Вона щодня займається грою на піаніно.'), ('læne sig', 'phrase', '013833bb-1425-5b87-9053-c7653b8f39bf', 1, 'verb', null, 'нахилятися, притулятися', 'Hun læner sig mod væggen, mens hun taler i telefon.', 'Вона спирається на стіну, розмовляючи по телефону.'), ('holde på', 'phrase', '0707e9eb-08bf-5873-832b-0e7d35f3c944', 1, 'verb', null, 'наполягати (на чомусь)', 'Han holder på, at vi skal tage af sted nu.', 'Він наполягає, щоб ми йшли зараз.'), ('falde fra', 'phrase', '046002ff-cac3-55d9-a214-5388eb28c90f', 1, 'verb', null, 'відсіюватися, вибувати (з групи, курсу)', 'Mange elever falder fra i løbet af det første år.', 'Багато студентів відсіюються протягом першого року.'), ('leve af', 'phrase', 'b616cf6f-7112-5f9b-a5c5-ebc2c80d856e', 1, 'verb', null, 'жити на (кошти)', 'De lever af en lille pension.', 'Вони живуть на невелику пенсію.'), ('leve med', 'phrase', '923eb2a9-aff3-5609-9fb9-f927f681839d', 1, 'verb', null, 'миритися з (чимось)', 'Jeg lever med støjen fra vejen.', 'Я мирюся з шумом дороги.'), ('udvikle sig', 'phrase', 'dc9dc530-6f24-5b8b-867e-9cae243dcb13', 1, 'verb', null, 'розвиватися', 'Byen har udviklet sig meget de sidste år.', 'Місто значно розвинулося за останні роки.'), ('bryde sammen', 'phrase', '7a6fff2f-1d66-5456-9fbe-8d0953725475', 1, 'verb', null, 'втрачати самовладання (від горя)', 'Hun brød sammen, da hun hørte nyheden.', 'Вона втратила самовладання, коли почула новину.'), ('om bord', 'phrase', '033732c3-83b3-5c6c-a288-3ef3fd8edfb2', 1, 'adverb', null, 'на борту', 'Passagererne gik om bord på færgen.', 'Пасажири сіли на пором.'), ('bestemme sig for', 'phrase', 'e5bae13a-8df1-5262-a8bc-230ef02c3585', 1, 'verb', null, 'вирішити (щось зробити), обрати', 'Jeg har bestemt mig for at lære dansk.', 'Я вирішив вивчити данську.'), ('hvem som helst', 'phrase', '1aba39f7-b973-5e0d-be7c-9a77d537612d', 1, 'phrase', null, 'хто завгодно', 'Du kan spørge hvem som helst om hjælp.', 'Ви можете звернутися за допомогою до будь-кого.'), ('tillade sig', 'phrase', '472ac294-91a8-5450-9be9-fbe3736baf33', 1, 'verb', null, 'дозволяти собі (щось, що зазвичай не дозволено)', 'Hun tillod sig et lille stykke kage til kaffen.', 'Вона дозволила собі маленький шматочок торта разом із кавою.'), ('tillade sig', 'phrase', 'a413a4eb-2e37-567b-ac13-bf805ad5804b', 2, 'verb', null, 'насмілюватися (робити щось зухвале)', 'Han tillod sig at afbryde chefen under mødet.', 'Він дозволив собі перебити начальника під час наради.'), ('sove over sig', 'phrase', '8233bd8e-d429-5bd6-b70f-c30088f08820', 1, 'verb', null, 'проспати (не прокинутися вчасно)', 'Jeg sov over mig i morges og kom for sent på arbejde.', 'Сьогодні вранці я проспав і запізнився на роботу.'), ('være afhængig af', 'phrase', '7b7428a0-cb73-5395-83f3-c97cec44f832', 1, 'verb', null, 'залежати від', 'Hun er afhængig af sin bil for at komme på arbejde.', 'Без машини вона не може дістатися до роботи.'), ('være afhængig af', 'phrase', '7d1599b5-b10c-56b4-8a64-d11e71bdefe6', 2, 'verb', null, 'бути залежним від', 'Min bror var afhængig af alkohol i mange år.', 'Мій брат багато років був залежний від алкоголю.'), ('røre sig', 'phrase', '30c6735e-8957-5e57-9741-16af095ab49c', 1, 'verb', null, 'рухатися', 'Jeg rører mig meget i løbet af dagen.', 'Я багато рухаюся вдень.'), ('røre ved', 'phrase', 'b8d36e35-a9f4-5e00-b0a1-fec562ec4987', 1, 'verb', null, 'торкатися (доторкатися)', 'Du må ikke røre ved den varme ovn.', 'Не чіпайте гарячу духовку.'), ('sige farvel til', 'phrase', '31ec7569-c257-51d7-a6f9-9bee4cbb98b9', 1, 'verb', null, 'прощатися з', 'Hun sagde farvel til sine venner i lufthavnen.', 'Вона попрощалася з друзями в аеропорту.'), ('komme af', 'phrase', '6e763cc2-7c4c-5f65-b253-d629789ea8df', 1, 'verb', null, 'походити від', 'Problemet kom af en misforståelse.', 'Проблема виникла через непорозуміння.'), ('komme op', 'phrase', '8a65a512-3bc0-5c22-b5fd-9f5e237e21d4', 1, 'verb', null, 'вставати (з ліжка)', 'Jeg kommer op klokken syv hver morgen.', 'Щоранку я встаю о сьомій.'), ('komme op', 'phrase', '742615c3-7839-5572-bb61-e991f6a43752', 2, 'verb', null, 'підніматися (нагору)', 'Børnene kommer op til os om aftenen.', 'Діти піднімаються до нас увечері.'), ('stå af', 'phrase', '2392379a-2352-528b-98b4-cc9ca924e260', 1, 'verb', null, 'виходити (з транспорту)', 'Jeg står af bussen ved stationen.', 'Я виходжу з автобуса на станції.'), ('sætte sig ind i', 'phrase', '392f5275-92b1-5150-9c7b-c51d53ce62f4', 1, 'verb', null, 'вникати (в тему, проблему)', 'Jeg sætter mig ind i de nye regler i aften.', 'Сьогодні ввечері я ознайомлюся з новими правилами.'), ('skrive af', 'phrase', 'cc7d95bb-fc0e-5188-8de8-b8d1dbcb92aa', 1, 'verb', null, 'списувати', 'Eleverne skrev af fra tavlen i timen.', 'Учні переписували з дошки під час уроку.'), ('komme igen', 'phrase', 'dbc4334b-5b6b-593c-833e-3caa46522f93', 1, 'verb', null, 'повертатися', 'Jeg kommer igen i morgen.', 'Я повернуся завтра.'), ('komme frem', 'phrase', 'aa7692a1-b892-55ea-b46f-0954dbbfb65f', 1, 'verb', null, 'з''являтися (ставати видимим)', 'Solen kom frem bag skyerne.', 'Сонце вийшло з-за хмар.'), ('komme frem', 'phrase', 'b3a99685-3e4d-592c-b50a-35db4018a52f', 2, 'verb', null, 'приходити (добиратися до місця)', 'Vi kom frem til stationen efter en time.', 'Ми приїхали на станцію через годину.'), ('sætte sig ned', 'phrase', '99a90562-f522-5f2e-b3c7-b1e20917976e', 1, 'verb', null, 'сідати', 'Han sætter sig ned på stolen og læser en bog.', 'Він сідає на стілець і читає книгу.'), ('have fri', 'phrase', 'a3ed6c81-de3d-59dc-a43b-6cc0ac20d625', 1, 'verb', null, 'мати вихідний', 'Jeg har fri i morgen, så vi kan tage på stranden.', 'Завтра у мене вихідний, тож ми можемо піти на пляж.'), ('kigge ind', 'phrase', 'b3c1a1d3-c041-5a8c-be78-25b68fbd48d1', 1, 'verb', null, 'зазирнути (ненадовго зайти)', 'Jeg kigger ind til dig i morgen.', 'Я зазирну до тебе завтра.'), ('køre forbi', 'phrase', '4249ba67-8858-567b-b4b7-d52f49cad661', 1, 'verb', null, 'проїжджати повз', 'Bussen kører forbi skolen hver morgen.', 'Щоранку автобус проїжджає повз школу.'), ('mangel på', 'phrase', '7031088c-2bd9-55cf-bcf0-c0eb97c9ad8b', 1, 'phrase', null, 'нестача (чогось)', 'Der er mangel på vand i byen.', 'У місті нестача води.'), ('forsvare sig', 'phrase', 'abec1d17-eb82-5f86-b47c-3de2dfc55127', 1, 'verb', null, 'захищатися', 'Han forsvarede sig mod kritikken.', 'Він захищався від критики.'), ('opholde sig', 'phrase', '58e520af-0604-5b1f-a63f-705291e310c6', 1, 'verb', null, 'перебувати (десь)', 'Vi opholder os mest i stuen om aftenen.', 'Ми більшість часу проводимо у вітальні ввечері.'), ('tjekke ind', 'phrase', '328e4ee9-b553-5e04-bb0c-1f681b697688', 1, 'verb', null, 'реєструватися (в готелі, на рейс)', 'Vi tjekker ind på hotellet klokken to.', 'Ми заселяємося в готелі о другій.'), ('blive forelsket i', 'phrase', '52e7d30f-0afc-5c02-ae78-9d1769f7e10e', 1, 'verb', null, 'закохуватися в', 'Hun blev forelsket i sin kollega.', 'Вона закохалася у свою колегу.'), ('være ked af det', 'phrase', '47410e7b-2c5b-58cf-b086-a5c5448eb426', 1, 'verb', null, 'шкодувати (про щось), засмучуватися', 'Jeg er ked af det, fordi min kat er syg.', 'Мені сумно, бо мій кіт хворий.'), ('skelne mellem', 'phrase', '5cdb0995-0c01-5fce-8425-8b056af22305', 1, 'verb', null, 'розрізняти (між)', 'Jeg kan ikke skelne mellem de to farver.', 'Я не можу розрізнити ці два кольори.'), ('snige sig', 'phrase', 'cadea705-583c-5829-94f6-ba02cd558145', 1, 'verb', null, 'крастися, пробиратися нишком', 'Han sniger sig ind i køkkenet om natten.', 'Він пробирається на кухню вночі.'), ('snige sig', 'phrase', '1967e2b0-6c75-5f16-a316-e64a9d06e0dc', 2, 'verb', null, 'вкрастися (про помилку, почуття)', 'Der sneg sig en fejl ind i teksten.', 'У текст закралася помилка.'), ('gå af', 'phrase', '0b2810e9-1016-530d-8f2c-86526a1e2996', 1, 'verb', null, 'йти у відставку (з посади)', 'Direktøren gik af efter skandalen.', 'Директор пішов у відставку після скандалу.'), ('gå af', 'phrase', '96dd718c-0f88-54f2-aa29-a74e34ce6cce', 2, 'verb', null, 'сходити (з транспорту)', 'Vi gik af bussen ved torvet.', 'Ми вийшли з автобуса на головній площі.'), ('gå af', 'phrase', '6e450959-966f-5205-b590-fd1290e1ddb0', 3, 'verb', null, 'відходити (про пляму)', 'Pletten gik af med sæbe.', 'Пляма змилася милом.'), ('gå i gang', 'phrase', '76406061-0372-58da-877e-90961d727daf', 1, 'verb', null, 'починати (справу, роботу)', 'Vi gik i gang med opvasken efter middagen.', 'Ми почали мити посуд після вечері.'), ('være klar til', 'phrase', '8940c08f-370b-5a0b-a7f4-54fae8b16799', 1, 'verb', null, 'бути готовим (до чогось)', 'Jeg er klar til at tage af sted nu.', 'Я готовий вирушати зараз.'), ('lade sig fortælle', 'phrase', 'f0e67ba9-a67e-5891-9164-fc571e82ebbd', 1, 'verb', null, 'чути (від когось)', 'Jeg har ladet mig fortælle, at butikken lukker tidligt i dag.', 'Мені сказали, що сьогодні магазин закривається раніше.'), ('følge af', 'phrase', 'd3767e03-6097-5061-93f7-7778e264be5a', 1, 'verb', null, 'випливати з (бути наслідком)', 'Det følger af reglerne, at du skal betale.', 'З правил випливає, що ви повинні платити.'), ('gå rundt', 'phrase', 'aa7e9b6f-d179-59f3-98f7-c1c98f767f68', 1, 'verb', null, 'обходити (перешкоду)', 'De gik rundt om det store hul i vejen.', 'Вони обійшли велику яму на дорозі.'), ('købe ind', 'phrase', '83d3bfad-2f3e-5b57-8fbb-0b24cc02a20a', 1, 'verb', null, 'купувати продукти', 'Vi køber ind til hele ugen om søndagen.', 'Ми закуповуємо продукти на цілий тиждень у неділю.'), ('føre sig', 'phrase', '8c23608c-d9e7-5088-a97e-8c0767c25723', 1, 'verb', null, 'поводитися (певним чином)', 'Han fører sig som en rigtig gentleman.', 'Він поводиться як справжній джентльмен.'), ('tage på i vægt', 'phrase', '3dde2b47-c4ce-57e1-aa38-5bd6a901bcb9', 1, 'verb', null, 'набирати вагу', 'Jeg tager på i vægt, hvis jeg spiser for meget slik.', 'Я набираю вагу, якщо їм забагато солодощів.'), ('få fat i', 'phrase', '90e64691-83ef-57b5-9531-041b0d72487e', 1, 'verb', null, 'зв''язатися (з кимось)', 'Jeg fik fat i lægen i går.', 'Вчора я зв''язався з лікарем.'), ('kendskab til', 'phrase', '105071a6-c50f-5334-abb4-5df2c597588b', 1, 'phrase', null, 'знання (чогось)', 'Han har et godt kendskab til dansk historie.', 'Він добре знає данську історію.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'uk'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'uk', text, pos, gender, example, example_translation, 'pipeline-phrases-0004' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
